# Shim: report the system reference BLAS (libblas.so.3 exports cblas_*).
# Returning libraries=['blas'] makes sklearn's get_blas_info() link -lblas
# and skips compiling the bundled fallback cblas sources.


def get_info(name, notfound_action=0):
    if name in ('blas_opt', 'blas', 'lapack_opt', 'lapack'):
        return {'libraries': ['blas'], 'library_dirs': [],
                'include_dirs': [], 'define_macros': []}
    return {}


